        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,2) p50_ms, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE span_name IN ('SELECT ts.orders','SELECT order.entity.Order','SELECT ts.orders_other') AND service_name IN ('ts-order-service','ts-order-other-service') GROUP BY ALL",
